values
('vocab_urge','urge','verb','to strongly encourage someone to do something','[{"senseId":"urge_1","meaning":"to strongly encourage someone to do something","acceptedParaphrases":["strongly encourage","press"],"masteryContexts":[{"contextId":"u1_08_urge_meaning","text":"Doctors strongly urge patients to take up gentle exercise because the benefits are so large, though the choice is always theirs.","meaning":"press someone strongly to act"},{"contextId":"u1_08_urge_paraphrase","text":"Friends who live here urge new students to try the local food, which is cheap, delicious and unlike anything most newcomers have tasted.","meaning":"push someone firmly toward action"}],"contextDependentParaphrases":[],"misleadingDistractors":["forbid","ignore","estimate"],"grammarForms":{"base":"urge","thirdPerson":"urges","past":"urged","pastParticiple":"urged","ing":"urging"},"grammarPatterns":["urge + object + to-infinitive","be urged + to-infinitive"]}]'::jsonb,'["urgent","urgency","urgently"]'::jsonb,'[]'::jsonb,'live'),
('vocab_demand','demand','verb','to require a lot of effort, skill, attention, or resources','[{"senseId":"demand_1","meaning":"to require a lot of effort, skill, attention, or resources","acceptedParaphrases":["require","need"],"masteryContexts":[{"contextId":"u1_10_demand_meaning","text":"Marathon training can demand patience, discipline and a great deal of time.","meaning":"require considerable effort or attention"},{"contextId":"u1_10_demand_paraphrase","text":"Learning two languages at once will demand a lot of concentration.","meaning":"place heavy requirements on something"}],"contextDependentParaphrases":[],"misleadingDistractors":["avoid","permit","relax"],"grammarForms":{"base":"demand","thirdPerson":"demands","past":"demanded","pastParticiple":"demanded","ing":"demanding"},"grammarPatterns":["demand + noun","demand + that-clause"]}]'::jsonb,'["demanding","demands"]'::jsonb,'["demand time","physically demanding"]'::jsonb,'live')
