insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_unfamiliar','unfamiliar','adjective','not known or recognised because you have not experienced it before','[{"senseId":"unfamiliar_1","meaning":"not known or recognised because you have not experienced it before","acceptedParaphrases":["not known","new to you"],"masteryContexts":[{"contextId":"u1_14_unfamiliar_meaning","text":"Many of the rules in baseball seemed unfamiliar to the exchange students, because none of them had ever watched a game.","meaning":"not recognised from previous experience"},{"contextId":"u1_14_unfamiliar_paraphrase","text":"Moving to another country means getting used to unfamiliar food, customs and routines.","meaning":"new or unknown to someone"}],"contextDependentParaphrases":[],"misleadingDistractors":["famous","comfortable","ordinary"]}]'::jsonb,'["familiar","familiarity","familiarise"]'::jsonb,'[]'::jsonb,'live'),
('vocab_opponent','opponent','noun','a person or team you compete against','[{"senseId":"opponent_1","meaning":"a person or team you compete against","acceptedParaphrases":["competitor you face","rival"],"masteryContexts":[{"contextId":"u1_16_opponent_meaning","text":"The tennis player shook hands with her opponent, who had just beaten her in three sets.","meaning":"person or team competing against you"},{"contextId":"u1_16_opponent_paraphrase","text":"Before the game, the captain studied video of the other team’s goalkeeper to find the opponent’s weaknesses.","meaning":"the other side in a contest"}],"contextDependentParaphrases":[],"misleadingDistractors":["coach","spectator","teammate"]}]'::jsonb,'["oppose","opposition","opposite"]'::jsonb,'[]'::jsonb,'live'),
('vocab_intense','intense','adjective','very strong, serious, or demanding','[{"senseId":"intense_1","meaning":"very strong, serious, or demanding","acceptedParaphrases":["very demanding","extremely strong"],"masteryContexts":[{"contextId":"u1_17_intense_meaning","text":"Players faced intense pressure in the final minutes, with the score level and the whole crowd roaring.","meaning":"extreme in strength or effort"},{"contextId":"u1_17_intense_paraphrase","text":"The sun was so intense that the runners had to stop for water every few minutes.","meaning":"requiring very great energy or focus"}],"contextDependentParaphrases":[],"misleadingDistractors":["gentle","casual","brief"]}]'::jsonb,'["intensity","intensely","intensify"]'::jsonb,'["intense competition","intense training"]'::jsonb,'live')
insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_generation','generation','noun','a group of people born and living at roughly the same time','[{"senseId":"generation_1","meaning":"a group of people born and living at roughly the same time","acceptedParaphrases":["age group","people of the same era"],"masteryContexts":[{"contextId":"u1_25_generation_meaning","text":"People born in the nineties are often described as part of the same generation, because they grew up with similar technology.","meaning":"people from roughly the same age period"},{"contextId":"u1_25_generation_paraphrase","text":"A new generation of players, all born after the year 2005, is replacing the champions who dominated the sport for years.","meaning":"group born during a similar era"}],"contextDependentParaphrases":[],"misleadingDistractors":["team","audience","committee"],"teacherNote":"Use the age-group sense here."}]'::jsonb,'["generate","generational","generator"]'::jsonb,'[]'::jsonb,'live')
insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_estimated','estimated','adjective','calculated or judged approximately rather than known exactly','[{"senseId":"estimated_1","meaning":"calculated or judged approximately rather than known exactly","acceptedParaphrases":["approximate","roughly calculated"],"masteryContexts":[{"contextId":"u1_32_estimated_meaning","text":"The estimated crowd at the final was fifty thousand, though officials admitted that nobody had counted exactly.","meaning":"worked out approximately, not exactly"},{"contextId":"u1_32_estimated_paraphrase","text":"The estimated cost of the new stadium is two hundred million pounds, but the final bill may be higher.","meaning":"based on calculation rather than certainty"}],"contextDependentParaphrases":[],"misleadingDistractors":["confirmed","exact","historic"]}]'::jsonb,'["estimate","estimation","underestimate"]'::jsonb,'["estimated cost","estimated number"]'::jsonb,'live'),
('vocab_minimum','minimum','noun','the smallest amount, number, or level allowed or needed','[{"senseId":"minimum_1","meaning":"the smallest amount, number, or level allowed or needed","acceptedParaphrases":["lowest amount","least"],"masteryContexts":[{"contextId":"u1_34_minimum_meaning","text":"Players must complete a minimum of three training sessions each week.","meaning":"lowest acceptable amount or level"},{"contextId":"u1_34_minimum_paraphrase","text":"The minimum age for competitors is sixteen.","meaning":"smallest quantity that meets a requirement"}],"contextDependentParaphrases":[],"misleadingDistractors":["maximum","average","estimate"],"teacherNote":"Often paraphrased structurally as at least rather than by a direct noun synonym."}]'::jsonb,'["minimal","minimise","minimally"]'::jsonb,'["minimum age","minimum requirement"]'::jsonb,'live'),
('vocab_championship','championship','noun','a major competition that decides the best player or team','[{"senseId":"championship_1","meaning":"a major competition that decides the best player or team","acceptedParaphrases":["title competition","major contest"],"masteryContexts":[{"contextId":"u1_35_championship_meaning","text":"She qualified for the national championship after winning the regional event.","meaning":"major contest deciding the title winner"},{"contextId":"u1_35_championship_paraphrase","text":"He trained all year for the championship.","meaning":"competition that determines the leading player"}],"contextDependentParaphrases":[],"misleadingDistractors":["practice session","friendly match","lesson"]}]'::jsonb,'["champion","championships"]'::jsonb,'["national championship","win the championship"]'::jsonb,'live'),
('vocab_relatively','relatively','adverb','to a fairly limited degree when compared with something else','[{"senseId":"relatively_1","meaning":"to a fairly limited degree when compared with something else","acceptedParaphrases":["comparatively","fairly"],"masteryContexts":[{"contextId":"u1_37_relatively_meaning","text":"The new sports centre is relatively small compared with the old stadium.","meaning":"to a degree judged by comparison"},{"contextId":"u1_37_relatively_paraphrase","text":"The route is relatively easy compared with the mountain course.","meaning":"fairly so compared with something else"}],"contextDependentParaphrases":[],"misleadingDistractors":["completely","extremely","exactly"]}]'::jsonb,'["relative","relatives","relates"]'::jsonb,'[]'::jsonb,'live'),
('vocab_incredible','incredible','adjective','extremely impressive, surprising, or difficult to believe','[{"senseId":"incredible_1","meaning":"extremely impressive, surprising, or difficult to believe","acceptedParaphrases":["amazing","extraordinary"],"masteryContexts":[{"contextId":"u1_40_incredible_meaning","text":"Her final lap was incredible and broke the school record.","meaning":"extremely impressive or surprising"},{"contextId":"u1_40_incredible_paraphrase","text":"The goalkeeper made an incredible save in the final seconds.","meaning":"exceptionally remarkable and hard to believe"}],"contextDependentParaphrases":[],"misleadingDistractors":["ordinary","predictable","minor"]}]'::jsonb,'["incredibly"]'::jsonb,'[]'::jsonb,'live')
insert into public.vocabulary_items
