values
('vocab_historic','historic','adjective','important in history or likely to be remembered for a long time','[{"senseId":"historic_1","meaning":"important in history or likely to be remembered for a long time","acceptedParaphrases":["historically important","momentous"],"masteryContexts":[{"contextId":"u1_42_historic_meaning","text":"The victory was a historic moment for the small club, and fans still talk about it.","meaning":"important enough to matter in history"},{"contextId":"u1_42_historic_paraphrase","text":"The team’s first international victory was historic.","meaning":"likely to be remembered historically"}],"contextDependentParaphrases":[],"misleadingDistractors":["old-fashioned","ordinary","recent"],"teacherNote":"Means important in history, not simply old or related to history."}]'::jsonb,'["history","historical","historian"]'::jsonb,'["historic victory","historic moment"]'::jsonb,'live'),
('vocab_craftspeople','craftspeople','noun','people skilled at making things by hand','[{"senseId":"craftspeople_1","meaning":"people skilled at making things by hand","acceptedParaphrases":["skilled makers","artisans"],"masteryContexts":[{"contextId":"u1_45_craftspeople_meaning","text":"Local craftspeople make the wooden equipment using traditional methods.","meaning":"skilled workers who make things by hand"},{"contextId":"u1_45_craftspeople_paraphrase","text":"Skilled makers demonstrated how the traditional equipment was made.","meaning":"people with specialist hand-making skills"}],"contextDependentParaphrases":[],"misleadingDistractors":["spectators","athletes","customers"]}]'::jsonb,'["craft","craftsmanship","crafted"]'::jsonb,'[]'::jsonb,'live'),
('vocab_expansion','expansion','noun','an increase in size, range, or amount','[{"senseId":"expansion_1","meaning":"an increase in size, range, or amount","acceptedParaphrases":["growth","increase"],"masteryContexts":[{"contextId":"u1_47_expansion_meaning","text":"The club’s expansion created space for several new sports.","meaning":"process of becoming larger in scope"},{"contextId":"u1_47_expansion_paraphrase","text":"The expansion of the league has attracted more young players.","meaning":"growth in size, range or amount"}],"contextDependentParaphrases":[],"misleadingDistractors":["reduction","delay","selection"]}]'::jsonb,'["expand","expanded","expanding"]'::jsonb,'["rapid expansion","business expansion"]'::jsonb,'live')
